-- Development seed data. Loaded by `supabase db reset` (local) only; never by migrations,
-- so no real deployment gets these users or this data. All of it is synthetic.
--
-- Dev sign-in (local only): any of the emails below, password LocalDev2026pw
-- Sarah Chen is an admin; everyone else is a member.

DO $$
DECLARE
  uid uuid;
  u jsonb;
  users_data jsonb := '[
    {
      "email": "sarah.chen@example.com",
      "display_name": "Sarah Chen",
      "job_title": "Head of Information Security",
      "department": "Security",
      "tags": ["SOC 2","ISO 27001","risk management","governance","audit","compliance","GDPR","HIPAA"]
    },
    {
      "email": "james.okafor@example.com",
      "display_name": "James Okafor",
      "job_title": "Cloud Security Architect",
      "department": "Engineering",
      "tags": ["cloud security","AWS","Azure","GCP","zero trust","network security","firewall","VPN","encryption","TLS"]
    },
    {
      "email": "priya.sharma@example.com",
      "display_name": "Priya Sharma",
      "job_title": "Compliance Manager",
      "department": "Legal & Compliance",
      "tags": ["GDPR","CCPA","HIPAA","SOC 2","ISO 27001","audit","policy","data privacy","governance"]
    },
    {
      "email": "tom.richardson@example.com",
      "display_name": "Tom Richardson",
      "job_title": "Application Security Engineer",
      "department": "Engineering",
      "tags": ["application security","OWASP","SDLC","code review","penetration testing","vulnerability management","patch management"]
    },
    {
      "email": "maya.patel@example.com",
      "display_name": "Maya Patel",
      "job_title": "Identity & Access Manager",
      "department": "Security",
      "tags": ["access control","authentication","MFA","RBAC","SSO","identity","zero trust","privileged access"]
    },
    {
      "email": "daniel.webb@example.com",
      "display_name": "Daniel Webb",
      "job_title": "Security Operations Lead",
      "department": "Security Operations",
      "tags": ["incident response","security operations","SIEM","forensics","threat detection","SOC","monitoring"]
    },
    {
      "email": "lisa.huang@example.com",
      "display_name": "Lisa Huang",
      "job_title": "Data Protection Officer",
      "department": "Legal & Compliance",
      "tags": ["data privacy","GDPR","CCPA","data classification","data retention","encryption","AES-256","key management"]
    },
    {
      "email": "marcus.johnson@example.com",
      "display_name": "Marcus Johnson",
      "job_title": "Infrastructure Security Engineer",
      "department": "Engineering",
      "tags": ["network security","firewall","VPN","physical security","data center","business continuity","DR","patch management"]
    }
  ]';
BEGIN
  FOR u IN SELECT * FROM jsonb_array_elements(users_data)
  LOOP
    SELECT id INTO uid FROM auth.users WHERE email = u->>'email';
    IF uid IS NULL THEN
      uid := gen_random_uuid();
      -- Empty strings (not NULL) for the token columns: GoTrue cannot read NULLs there.
      INSERT INTO auth.users (
        instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
        raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
        confirmation_token, recovery_token, email_change_token_new, email_change
      ) VALUES (
        '00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated',
        u->>'email', crypt('LocalDev2026pw', gen_salt('bf')), now(),
        '{"provider":"email","providers":["email"]}',
        jsonb_build_object('display_name', u->>'display_name'), now(), now(),
        '', '', '', ''
      );
      INSERT INTO auth.identities (id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at)
      VALUES (gen_random_uuid(), uid, uid::text, 'email',
              jsonb_build_object('sub', uid::text, 'email', u->>'email', 'email_verified', true), now(), now(), now());
    END IF;

    -- The on_auth_user_created trigger has already created a bare profile; fill it in.
    UPDATE public.user_profiles SET
      display_name   = u->>'display_name',
      job_title      = u->>'job_title',
      department     = u->>'department',
      expertise_tags = ARRAY(SELECT jsonb_array_elements_text(u->'tags')),
      is_admin       = (u->>'email' = 'sarah.chen@example.com')
    WHERE id = uid;
  END LOOP;
END $$;

-- BEGIN KNOWLEDGE BASE (generated by npm run demo:seed; do not edit by hand)
-- The knowledge base: the 100 synthetic entries in sample-data/security-qa.csv, in file order,
-- so their refs (KB-0001 onwards) match the evaluations and the recorded demo drafts. Added and
-- reviewed by the admin. Skipped if the knowledge base already has entries.
DO $kb$
DECLARE admin uuid := (SELECT id FROM auth.users WHERE email = 'sarah.chen@example.com');
BEGIN
  IF EXISTS (SELECT 1 FROM public.kb_entries) THEN RETURN; END IF;
  INSERT INTO public.kb_entries (question, answer, tags, source, origin, origin_ref, created_by)
  SELECT v.q, v.a, v.t, v.s, 'seed', 'sample-data/security-qa.csv', admin
    FROM (VALUES
      (1, 'How does your organization encrypt data at rest?', 'All data at rest is encrypted using AES-256 encryption across storage systems, databases, and backup media. Encryption keys are managed through a dedicated key management service (KMS) with strict access controls and regular rotation schedules. Hardware Security Modules (HSMs) are used for root key protection, and encryption coverage is validated through quarterly audits.', ARRAY['encryption', 'data protection', 'AES-256', 'key management']::text[], 'Data Protection Policy v3.1'),
      (2, 'How does your organization encrypt data in transit?', 'All data in transit is protected using TLS 1.2 or higher, with TLS 1.3 preferred for new integrations. Weak cipher suites are explicitly disabled, and certificate management follows a documented lifecycle process including automated renewal alerts. Internal service-to-service communication is also encrypted via mutual TLS (mTLS) within our zero-trust architecture.', ARRAY['encryption', 'TLS', 'data in transit', 'certificates']::text[], 'Network Security Policy v2.4'),
      (3, 'Describe your access control framework.', 'Access control is governed by a least-privilege, role-based access control (RBAC) model aligned with ISO 27001 Annex A controls. All access rights are reviewed quarterly through a formal access recertification process, and any changes are subject to approval workflows documented in our Access Control Policy. Privileged access is further restricted via Privileged Access Management (PAM) tooling with session recording.', ARRAY['access control', 'RBAC', 'least privilege', 'PAM']::text[], 'Access Control Policy v1.5'),
      (4, 'What multi-factor authentication (MFA) controls are in place?', 'MFA is mandatory for all employees, contractors, and third-party users accessing corporate systems, including VPN, SSO, email, and cloud platforms. Phishing-resistant MFA methods such as FIDO2 hardware tokens and authenticator apps are preferred over SMS-based OTP. MFA enforcement is monitored centrally, and exceptions require CISO-level approval with compensating controls.', ARRAY['MFA', 'authentication', 'identity', 'access control']::text[], 'Authentication Policy v2.0'),
      (5, 'What is your data retention and disposal policy?', 'Data retention schedules are defined per data classification category and legal/regulatory requirements, ranging from 1 year for operational logs to 7 years for financial records. Data disposal follows NIST SP 800-88 guidelines, including cryptographic erasure for SSDs and physical destruction certificates for decommissioned hardware. Retention schedules are reviewed annually by Legal, Compliance, and Security teams.', ARRAY['data retention', 'data disposal', 'compliance', 'NIST']::text[], 'Data Retention and Disposal Policy v1.8'),
      (6, 'How does your organization handle security incidents?', 'Our incident response program follows the NIST SP 800-61 framework with defined phases: preparation, detection, containment, eradication, recovery, and post-incident review. A dedicated Security Incident Response Team (SIRT) is on-call 24/7, and incidents are categorized by severity with associated SLA targets for response and notification. Post-incident reviews are conducted within 5 business days and findings are tracked to closure.', ARRAY['incident response', 'SIRT', 'NIST', 'SLA']::text[], 'Incident Response Plan v3.0'),
      (7, 'Describe your vulnerability management program.', 'Vulnerabilities are identified through a combination of continuous automated scanning, external penetration testing, threat intelligence feeds, and vendor advisories. All findings are risk-rated using CVSS scoring and tracked in a centralized vulnerability management platform with defined remediation SLAs: Critical (24 hours), High (7 days), Medium (30 days). Metrics on mean time to remediate are reported monthly to senior leadership.', ARRAY['vulnerability management', 'CVSS', 'scanning', 'remediation']::text[], 'Vulnerability Management Policy v2.2'),
      (8, 'What business continuity and disaster recovery plans does your organization maintain?', 'A formal Business Continuity Plan (BCP) and Disaster Recovery Plan (DRP) are maintained, tested annually, and updated following any significant organizational or infrastructure change. RTO and RPO targets are defined per system criticality and validated through tabletop exercises and full failover tests. Results of DR tests are documented, reviewed by executive leadership, and gaps are tracked in the risk register.', ARRAY['BCP', 'DRP', 'RTO', 'RPO']::text[], 'Business Continuity Policy v2.1'),
      (9, 'How do you manage third-party and vendor security risk?', 'All vendors with access to our systems or data undergo a tiered security assessment process based on data sensitivity and access level, including questionnaire reviews, SOC 2 report evaluation, and on-site assessments for critical vendors. Vendor contracts include mandatory security and data protection clauses, right-to-audit provisions, and breach notification requirements. Vendor risk ratings are reassessed annually or upon material change.', ARRAY['vendor management', 'third-party risk', 'supply chain', 'due diligence']::text[], 'Third-Party Risk Management Policy v1.9'),
      (10, 'Describe your network security architecture.', 'Network security is built on a defense-in-depth model incorporating segmentation, next-generation firewalls (NGFW), intrusion detection/prevention systems (IDS/IPS), and secure DNS filtering. Network zones are defined based on data sensitivity and system criticality, with micro-segmentation applied to limit lateral movement. All network access rules are reviewed quarterly and unauthorized traffic is alerted in real time via our SIEM.', ARRAY['network security', 'firewall', 'segmentation', 'IDS/IPS']::text[], 'Network Security Policy v2.4'),
      (11, 'What endpoint protection controls are deployed?', 'All endpoints are protected by an EDR (Endpoint Detection and Response) solution providing real-time threat detection, behavioral analysis, and automated response capabilities. Endpoints must be enrolled in MDM before accessing corporate resources, and compliance checks enforce OS patching, disk encryption, and screen lock policies. USB and removable media usage is restricted by policy and enforced through DLP controls.', ARRAY['endpoint security', 'EDR', 'MDM', 'DLP']::text[], 'Endpoint Security Policy v2.0'),
      (12, 'How do you secure cloud environments?', 'Cloud security is managed through a Cloud Security Posture Management (CSPM) platform that continuously monitors configurations against CIS benchmarks and internal baselines. All cloud infrastructure is provisioned via Infrastructure-as-Code (IaC) templates with embedded security controls reviewed through automated policy-as-code checks in the CI/CD pipeline. Shared responsibility boundaries are documented for each cloud provider relationship.', ARRAY['cloud security', 'CSPM', 'IaC', 'CIS benchmarks']::text[], 'Cloud Security Policy v1.7'),
      (13, 'Describe your application security practices.', 'Application security is embedded throughout the SDLC, including mandatory threat modeling for new features, SAST and DAST scanning integrated into CI/CD pipelines, and developer security training aligned with OWASP Top 10. All production code undergoes peer review with security sign-off for high-risk changes, and critical applications receive annual third-party penetration testing. Discovered vulnerabilities are tracked and remediated according to our defined SLAs.', ARRAY['application security', 'SAST', 'DAST', 'OWASP']::text[], 'Application Security Policy v1.6'),
      (14, 'What physical security controls protect your facilities?', 'Physical access to data centers and office facilities is controlled through badge-based access systems with multi-factor authentication at sensitive areas such as server rooms. Access logs are retained for 12 months, visitor access is escorted and logged, and CCTV surveillance covers entry/exit points and critical infrastructure areas with 90-day retention. Physical security controls are reviewed annually through internal audits and validated by co-location provider compliance certifications.', ARRAY['physical security', 'access control', 'CCTV', 'data center']::text[], 'Physical Security Policy v1.3'),
      (15, 'How does your organization comply with GDPR?', 'Our GDPR compliance program is overseen by a designated Data Protection Officer (DPO) and encompasses data mapping, privacy impact assessments (DPIAs), and a documented legal basis for each processing activity. Data subject rights requests (access, erasure, portability) are handled through a defined workflow with a 30-day response SLA. Annual privacy audits validate compliance, and staff receive mandatory GDPR training upon hire and annually thereafter.', ARRAY['GDPR', 'privacy', 'DPO', 'data subject rights']::text[], 'Privacy and Data Protection Policy v2.5'),
      (16, 'How does your organization comply with HIPAA requirements?', 'Our HIPAA compliance program covers all three rules—Privacy, Security, and Breach Notification—and is supported by designated Privacy and Security Officers. PHI is encrypted at rest and in transit, access is restricted to minimum-necessary principles, and all workforce members handling PHI complete annual HIPAA training. Business Associate Agreements (BAAs) are executed with all vendors who process PHI on our behalf, and we conduct annual HIPAA risk assessments.', ARRAY['HIPAA', 'PHI', 'privacy', 'compliance']::text[], 'HIPAA Compliance Policy v1.4'),
      (17, 'What SOC 2 certifications does your organization hold?', 'We maintain a SOC 2 Type II report covering the Trust Services Criteria for Security, Availability, and Confidentiality, issued by an independent AICPA-accredited auditor. The audit period covers a minimum of six months and reports are refreshed annually, with bridge letters available upon request for periods between reports. Copies of the report are available under NDA to qualified prospective and current customers.', ARRAY['SOC 2', 'compliance', 'audit', 'Trust Services Criteria']::text[], 'SOC 2 Compliance Program v1.0'),
      (18, 'How does your organization align with ISO 27001?', 'Our Information Security Management System (ISMS) is certified to ISO/IEC 27001:2022 by an accredited certification body, covering all in-scope systems and processes defined in the Statement of Applicability (SoA). Surveillance audits occur annually, with full recertification every three years. Internal audits are conducted biannually, and management reviews ensure continual improvement of the ISMS.', ARRAY['ISO 27001', 'ISMS', 'certification', 'audit']::text[], 'Information Security Management System Policy v3.0'),
      (19, 'How frequently do you conduct penetration testing?', 'External penetration testing is conducted at minimum annually by a qualified third-party firm, with additional testing triggered by significant infrastructure changes, new product launches, or post-incident reviews. Internal red team exercises are performed on a risk-driven basis. All penetration test findings are tracked in our vulnerability management system, and critical and high findings are remediated within defined SLA windows before results are formally closed.', ARRAY['penetration testing', 'red team', 'vulnerability assessment', 'third-party']::text[], 'Penetration Testing Policy v1.2'),
      (20, 'Describe your security awareness training program.', 'All employees and contractors complete mandatory security awareness training upon onboarding and annually thereafter, covering phishing, social engineering, data handling, acceptable use, and incident reporting. Role-based supplemental training is required for developers, IT administrators, and users with access to sensitive data. Phishing simulation campaigns are run quarterly, and completion and click rates are tracked and reported to leadership.', ARRAY['security training', 'awareness', 'phishing simulation', 'compliance']::text[], 'Security Awareness Training Policy v2.1'),
      (21, 'What logging and monitoring capabilities do you have?', 'A centralized SIEM platform aggregates logs from all critical systems including firewalls, endpoints, identity providers, cloud platforms, and applications with defined log retention of 12 months online and 24 months archived. Detection rules are tuned based on threat intelligence and mapped to MITRE ATT&CK framework tactics and techniques. The security operations center (SOC) monitors alerts 24/7 with documented escalation procedures.', ARRAY['logging', 'monitoring', 'SIEM', 'SOC']::text[], 'Security Monitoring and Logging Policy v2.3'),
      (22, 'How is change management handled for security-impacting changes?', 'All changes to production systems, infrastructure, and security controls follow a formal change management process aligned with ITIL principles, requiring documented risk assessment, rollback plans, and approval from a Change Advisory Board (CAB). Emergency changes undergo expedited review with post-change documentation and root cause analysis. Change records are retained and reviewed during security audits.', ARRAY['change management', 'ITIL', 'CAB', 'risk assessment']::text[], 'Change Management Policy v1.7'),
      (23, 'What backup and recovery procedures are in place?', 'Critical systems and data are backed up daily with full backups weekly, stored in geographically separate locations with encryption at rest. Backup integrity is validated through automated verification checks and manual restoration tests conducted quarterly. Recovery procedures are documented in run books, and RTO/RPO metrics are tested and reported against defined targets during annual DR exercises.', ARRAY['backup', 'recovery', 'RTO', 'RPO']::text[], 'Backup and Recovery Policy v2.0'),
      (24, 'How does your organization manage user identities and access provisioning?', 'Identity lifecycle management is handled through an Identity Governance and Administration (IGA) platform that automates provisioning, de-provisioning, and access recertification workflows. Joiner-mover-leaver processes are defined with SLA targets, and terminated user access is revoked within 4 hours of HR notification. All access requests require documented business justification and manager approval prior to provisioning.', ARRAY['identity management', 'IGA', 'provisioning', 'access governance']::text[], 'Identity and Access Management Policy v2.6'),
      (25, 'Describe your zero trust implementation.', 'Our zero trust architecture is based on the NIST SP 800-207 framework, enforcing continuous verification of users, devices, and applications regardless of network location. Key capabilities include identity-aware proxies, device compliance checks before resource access, microsegmentation, and just-in-time privileged access. Zero trust maturity is assessed annually against a published roadmap with board-level visibility.', ARRAY['zero trust', 'NIST', 'microsegmentation', 'identity']::text[], 'Zero Trust Architecture Policy v1.1'),
      (26, 'How do you secure APIs exposed to external consumers?', 'All external APIs require authenticated access via OAuth 2.0 or API keys with defined scopes and expiry windows. Rate limiting, input validation, and output encoding are enforced at the API gateway layer, and all API traffic is logged and monitored for anomalies. New APIs undergo mandatory security review including threat modeling and OWASP API Security Top 10 assessment before production deployment.', ARRAY['API security', 'OAuth', 'rate limiting', 'OWASP']::text[], 'API Security Policy v1.3'),
      (27, 'What mobile device management policies are in place?', 'All corporate and BYOD devices that access company resources must be enrolled in an MDM platform, which enforces encryption, screen lock, remote wipe capability, and current OS patch levels. BYOD devices are containerized to separate corporate data from personal data, and access to sensitive applications is restricted to managed devices. Device compliance posture is evaluated in real time as part of our zero trust conditional access policies.', ARRAY['MDM', 'mobile device', 'BYOD', 'endpoint security']::text[], 'Mobile Device Management Policy v1.4'),
      (28, 'How is security integrated into your software development lifecycle (SDLC)?', 'Security is integrated at every phase of the SDLC through our DevSecOps program, which includes threat modeling during design, mandatory SAST/DAST scans in CI/CD pipelines, software composition analysis (SCA) for open-source dependencies, and pre-deployment security sign-off. Developers complete secure coding training annually, and security champions are embedded within engineering teams to drive adoption. Security debt is tracked and prioritized alongside feature work.', ARRAY['SDLC', 'DevSecOps', 'secure coding', 'CI/CD']::text[], 'Secure Development Lifecycle Policy v2.2'),
      (29, 'How does your organization manage information security risk?', 'Information security risks are identified and managed through a formal risk management framework aligned with ISO 31000 and NIST RMF. A risk register is maintained, reviewed quarterly, and presented to the Board and executive leadership. Risk treatment decisions—accept, mitigate, transfer, or avoid—are documented with ownership and target remediation dates, and residual risk is tracked against defined risk appetite thresholds.', ARRAY['risk management', 'risk register', 'ISO 31000', 'NIST RMF']::text[], 'Information Security Risk Management Policy v2.0'),
      (30, 'What security governance structure is in place?', 'Information security governance is led by a Chief Information Security Officer (CISO) who reports directly to the CEO and provides quarterly updates to the Board of Directors. A Security Steering Committee comprising senior leadership from IT, Legal, Compliance, and Operations meets monthly to review security posture, policy updates, and risk decisions. Security KPIs and KRIs are tracked via a formal security metrics program.', ARRAY['security governance', 'CISO', 'steering committee', 'KPIs']::text[], 'Information Security Governance Policy v1.5'),
      (31, 'How do you manage privileged access accounts?', 'Privileged accounts are inventoried and managed through a Privileged Access Management (PAM) solution that enforces just-in-time access, session recording, and password vaulting with automated rotation. Standing privileged access is eliminated wherever possible in favor of time-limited, approval-gated elevation. Privileged account activity is subject to enhanced monitoring and anomaly alerting within the SIEM.', ARRAY['privileged access', 'PAM', 'just-in-time', 'session recording']::text[], 'Privileged Access Management Policy v1.6'),
      (32, 'Describe your data classification scheme.', 'Data is classified into four tiers—Public, Internal, Confidential, and Restricted—based on sensitivity and potential impact of unauthorized disclosure. Classification is applied at the point of creation and drives downstream controls including encryption requirements, access restrictions, and handling procedures. Data owners are accountable for correct classification, and the data classification taxonomy is reviewed annually.', ARRAY['data classification', 'data governance', 'sensitivity', 'information security']::text[], 'Data Classification Policy v2.0'),
      (33, 'How does your organization detect and prevent insider threats?', 'Insider threat detection leverages a combination of User and Entity Behavior Analytics (UEBA) integrated with the SIEM, DLP controls monitoring sensitive data movement, and privileged access session recording. HR-triggered reviews are initiated for employees under performance management or in notice periods. The insider threat program is governed by a cross-functional committee including HR, Legal, and Security.', ARRAY['insider threat', 'UEBA', 'DLP', 'behavioral analytics']::text[], 'Insider Threat Program Policy v1.2'),
      (34, 'What controls are in place to prevent data loss?', 'A Data Loss Prevention (DLP) solution is deployed across endpoints, email, and cloud platforms to detect and block unauthorized transmission of sensitive data based on content inspection and contextual policies. DLP policies are tuned against the data classification taxonomy, and violations generate real-time alerts for SOC review. Quarterly DLP policy reviews ensure alignment with evolving business data flows and regulatory requirements.', ARRAY['DLP', 'data loss prevention', 'data protection', 'monitoring']::text[], 'Data Loss Prevention Policy v1.4'),
      (35, 'How do you secure your email platform?', 'Email security is enforced through a secure email gateway providing anti-phishing, anti-malware, and spam filtering, complemented by DMARC, DKIM, and SPF records to prevent domain spoofing. Advanced threat protection scans attachments and URLs in sandboxed environments, and suspicious emails are quarantined for review. Security awareness training includes phishing simulation exercises to reinforce user vigilance.', ARRAY['email security', 'phishing', 'DMARC', 'secure gateway']::text[], 'Email Security Policy v1.5'),
      (36, 'What controls govern remote access to your environment?', 'Remote access is provided exclusively through a zero-trust network access (ZTNA) solution or SSL VPN requiring MFA and device compliance verification prior to connection. Remote sessions are logged and monitored, and split tunneling is disabled to ensure all traffic is inspected. Access is granted based on least-privilege principles with session timeouts enforced after periods of inactivity.', ARRAY['remote access', 'VPN', 'ZTNA', 'MFA']::text[], 'Remote Access Policy v2.1'),
      (37, 'How do you manage security patches and updates?', 'Patch management follows a defined cycle: critical patches are deployed within 24–72 hours of release, high-severity patches within 7 days, and routine patches within 30 days. Automated patch deployment is used for endpoints and servers where possible, with exceptions tracked and risk-accepted by the CISO. Patch compliance metrics are reviewed weekly, and non-compliant assets are escalated through the vulnerability management workflow.', ARRAY['patch management', 'vulnerability management', 'remediation', 'compliance']::text[], 'Patch Management Policy v2.3'),
      (38, 'Describe your security testing for web applications.', 'Web applications are assessed through a combination of automated DAST scans integrated into CI/CD pipelines and annual manual penetration tests by certified third-party testers. Testing covers OWASP Top 10 vulnerabilities, business logic flaws, and authentication weaknesses. All findings are risk-rated, assigned to owners, and tracked to remediation with evidence of fix validation prior to closure.', ARRAY['web application security', 'DAST', 'penetration testing', 'OWASP']::text[], 'Application Security Policy v1.6'),
      (39, 'How does your organization handle security exceptions and policy waivers?', 'Security exceptions are governed by a formal waiver process requiring documented business justification, risk assessment, compensating controls, and CISO or delegate approval. All approved exceptions are logged in the exception register with defined expiry dates, and exceptions are reviewed quarterly. Recurring exceptions trigger a policy review to assess whether the standard itself requires updating.', ARRAY['security exceptions', 'policy waiver', 'risk acceptance', 'governance']::text[], 'Information Security Exception Policy v1.1'),
      (40, 'What is your process for security configuration management?', 'System configurations are managed against documented CIS Benchmark-based hardening standards for all supported OS, database, and application types. Configuration compliance is continuously monitored via automated tooling, with drift alerts triggering remediation workflows within defined SLAs. Configuration baselines are reviewed and updated annually or upon significant platform change.', ARRAY['configuration management', 'CIS benchmarks', 'hardening', 'compliance']::text[], 'Security Configuration Management Policy v1.8'),
      (41, 'How do you handle security for cloud-native workloads and containers?', 'Container security is enforced through image scanning in the CI/CD pipeline using SCA and vulnerability analysis tools, with images stored in a private registry subject to policy-based admission controls. Runtime security monitoring detects anomalous container behavior, and Kubernetes clusters are hardened per CIS benchmarks with RBAC enforced at the namespace level. Secrets management for containerized workloads uses a dedicated vault solution rather than environment variables.', ARRAY['container security', 'Kubernetes', 'DevSecOps', 'cloud security']::text[], 'Container and Cloud-Native Security Policy v1.2'),
      (42, 'Describe your approach to security architecture reviews.', 'All new systems, significant infrastructure changes, and third-party integrations undergo a formal Security Architecture Review (SAR) process led by the security architecture team. Reviews include threat modeling, control gap analysis, and sign-off requirements before production approval. Findings are documented in architecture decision records and tracked to resolution.', ARRAY['security architecture', 'threat modeling', 'design review', 'governance']::text[], 'Security Architecture Review Policy v1.0'),
      (43, 'What is your approach to managing security for remote workers?', 'Remote workers are subject to the same security policies as on-site employees, enforced through MDM, endpoint protection, and ZTNA-based access controls. Security awareness training includes modules specific to home office security risks, such as unsecured Wi-Fi and physical eavesdropping. VPN usage is mandatory when accessing sensitive systems, and remote worker equipment is company-issued and managed.', ARRAY['remote work', 'endpoint security', 'VPN', 'awareness training']::text[], 'Remote Work Security Policy v1.3'),
      (44, 'How does your organization manage cryptographic key lifecycles?', 'Cryptographic keys are managed through a centralized Key Management Service (KMS) that enforces key generation, distribution, rotation, and destruction procedures aligned with NIST SP 800-57 guidance. Key rotation schedules are automated where supported, and HSMs protect master keys. Key usage is logged and audited, and key custodians are designated with clear separation of duties to prevent single points of compromise.', ARRAY['key management', 'cryptography', 'KMS', 'HSM']::text[], 'Cryptographic Key Management Policy v1.5'),
      (45, 'What controls are in place for database security?', 'Database security controls include role-based access with least-privilege principles, encrypted connections enforced for all client connections, and activity monitoring through database audit logging integrated with the SIEM. Privileged database accounts are managed via PAM with session recording, and sensitive data fields such as PII and financial information are masked or tokenized where feasible. Database configurations are audited against CIS benchmarks quarterly.', ARRAY['database security', 'access control', 'audit logging', 'encryption']::text[], 'Database Security Policy v1.4'),
      (46, 'How is DNS security managed within your environment?', 'DNS security is implemented through protective DNS filtering to block malicious domains at the resolver level, complemented by DNSSEC validation where supported by authoritative zones. DNS query logs are ingested into the SIEM and monitored for indicators of DNS tunneling, data exfiltration, and domain generation algorithm (DGA) activity. Internal DNS infrastructure is segregated from external resolvers and hardened per configuration baselines.', ARRAY['DNS security', 'DNSSEC', 'DNS filtering', 'monitoring']::text[], 'Network Security Policy v2.4'),
      (47, 'Describe your approach to security metrics and reporting.', 'Security metrics are organized into a balanced scorecard covering vulnerability posture, patch compliance, incident trends, training completion, and access recertification rates. Monthly operational metrics are reviewed by the security leadership team, and a quarterly executive dashboard is presented to the CISO and Board. Metrics are aligned with the NIST Cybersecurity Framework outcomes to provide a structured view of security maturity.', ARRAY['security metrics', 'reporting', 'KPIs', 'NIST CSF']::text[], 'Security Metrics and Reporting Policy v1.2'),
      (48, 'How does your organization manage software supply chain security?', 'Software composition analysis (SCA) tooling is integrated into CI/CD pipelines to identify known vulnerabilities in open-source and third-party libraries before deployment. A Software Bill of Materials (SBOM) is generated for all production applications and maintained in the software asset inventory. Vendor software assessments include review of the vendor''s own SDLC security practices and SBOM availability.', ARRAY['supply chain security', 'SBOM', 'SCA', 'DevSecOps']::text[], 'Software Supply Chain Security Policy v1.1'),
      (49, 'What privacy-by-design principles are applied in product development?', 'Privacy-by-design is a mandatory requirement for new product features and systems processing personal data, enforced through DPIAs for high-risk processing activities and privacy review checkpoints in the SDLC. Principles applied include data minimization, purpose limitation, storage limitation, and default privacy settings. Privacy review outcomes are documented and approved by the DPO before production deployment.', ARRAY['privacy by design', 'GDPR', 'DPIA', 'data minimization']::text[], 'Privacy by Design Policy v1.0'),
      (50, 'How does your organization protect against DDoS attacks?', 'DDoS protection is provided at the network perimeter through cloud-based scrubbing services with upstream filtering capacity exceeding 2 Tbps, supplemented by rate limiting and geo-blocking at the application layer. Detection thresholds are tuned to distinguish attack traffic from legitimate spikes, with automated mitigation triggered within minutes of threshold breach. DDoS response procedures are documented and tested during annual incident response exercises.', ARRAY['DDoS', 'network security', 'availability', 'incident response']::text[], 'Network Security Policy v2.4'),
      (51, 'What security controls are applied to wireless networks?', 'Corporate wireless networks use WPA3-Enterprise with 802.1X authentication tied to the corporate identity provider. Guest wireless networks are isolated on a separate VLAN with internet-only access and no connectivity to corporate resources. Rogue access point detection is performed continuously through wireless intrusion detection system (WIDS) capabilities, and the wireless network is scanned for unauthorized devices monthly.', ARRAY['wireless security', 'WPA3', '802.1X', 'network segmentation']::text[], 'Wireless Network Security Policy v1.3'),
      (52, 'How do you ensure secure destruction of physical media?', 'Physical media containing sensitive data is destroyed in accordance with NIST SP 800-88 guidelines, using degaussing for magnetic media and certified shredding or incineration for other media types. A Certificate of Destruction is obtained from certified third-party providers and retained for audit purposes. Media disposition records are maintained and reviewed during annual security audits.', ARRAY['media destruction', 'NIST SP 800-88', 'data disposal', 'physical security']::text[], 'Data Retention and Disposal Policy v1.8'),
      (53, 'Describe your approach to security during mergers, acquisitions, or divestitures.', 'A formal M&A security due diligence process is initiated at the Letter of Intent stage, assessing the target entity''s security posture, compliance status, known vulnerabilities, and open incidents. Integration planning includes a risk-based roadmap for aligning security controls, and sensitive data from the acquired entity is quarantined until access controls and data governance are validated. Security findings from due diligence are tracked through post-close integration milestones.', ARRAY['M&A security', 'due diligence', 'integration', 'risk management']::text[], 'M&A Security Due Diligence Policy v1.0'),
      (54, 'How does your organization manage password policies?', 'Password policies are enforced through the identity provider and require a minimum of 14 characters with complexity requirements, prohibit reuse of the last 12 passwords, and enforce maximum age of 90 days for privileged accounts. Compromised credential detection is integrated with the identity provider to block the use of passwords found in known breach databases. Passwords are stored using adaptive hashing algorithms (bcrypt or Argon2) and are never logged or transmitted in plaintext.', ARRAY['password management', 'authentication', 'identity', 'credential security']::text[], 'Authentication Policy v2.0'),
      (55, 'What security monitoring is performed on privileged users?', 'Privileged user activity is subject to enhanced monitoring including full session recording through the PAM platform, real-time UEBA analytics for anomalous behavior, and SIEM alerting on high-risk administrative actions such as bulk data access or security control modifications. Privileged user logs are stored in a write-once, tamper-evident log repository with 24-month retention. Privileged access reviews are conducted monthly.', ARRAY['privileged access', 'UEBA', 'monitoring', 'PAM']::text[], 'Privileged Access Management Policy v1.6'),
      (56, 'How does your organization approach threat intelligence?', 'Threat intelligence is aggregated from commercial threat intel feeds, ISAC memberships relevant to our industry, government advisories (CISA, NCSC), and open-source intelligence sources. Intelligence is operationalized through SIEM detection rule updates, vulnerability prioritization, and threat hunting campaigns. A formal threat intelligence program with a designated analyst function ensures intelligence is contextualized to our specific risk profile.', ARRAY['threat intelligence', 'SIEM', 'ISAC', 'threat hunting']::text[], 'Threat Intelligence Policy v1.1'),
      (57, 'Describe your security controls for SaaS applications.', 'SaaS applications used by the organization are inventoried and assessed against a baseline security standard covering SSO integration, MFA enforcement, data residency, logging availability, and compliance certifications. Shadow IT discovery tools identify unauthorized SaaS usage, and new SaaS procurement requires security approval. Data stored in SaaS platforms is classified, and SaaS-specific DLP policies enforce data protection requirements.', ARRAY['SaaS security', 'cloud security', 'shadow IT', 'access control']::text[], 'Cloud Security Policy v1.7'),
      (58, 'How does your organization manage security for DevOps environments?', 'DevOps environments including CI/CD pipelines, build servers, and developer tooling are subject to the same security standards as production environments, including access controls, vulnerability scanning, and secrets management. Secrets are managed through a dedicated vault solution with dynamic secret generation where supported, and hardcoded credentials in source code are detected through pre-commit hooks and pipeline scanning. Infrastructure drift from approved baselines triggers automated alerts.', ARRAY['DevOps security', 'CI/CD', 'secrets management', 'DevSecOps']::text[], 'Secure Development Lifecycle Policy v2.2'),
      (59, 'What processes are in place for security event triage and investigation?', 'Security events generated by the SIEM and other detection tools are triaged by the SOC using a documented playbook library covering common attack scenarios. Each alert is assigned a priority based on asset criticality and threat severity, with Tier 1 analysts handling initial triage and escalating to Tier 2 or Tier 3 for complex investigations. All investigations are documented in the case management platform with evidence preservation procedures followed throughout.', ARRAY['SOC', 'incident triage', 'playbooks', 'investigation']::text[], 'Security Operations Center Procedures v2.0'),
      (60, 'How does your organization manage access for terminated employees?', 'Upon confirmed employee termination, IT and HR follow a documented offboarding checklist that requires deactivation of all logical access within 4 hours of the termination event and physical access revocation on the same business day. Automated deprovisioning is triggered through IGA integration with the HR system. Offboarding records are maintained and sampled during quarterly access reviews and annual audits.', ARRAY['offboarding', 'access revocation', 'identity management', 'HR integration']::text[], 'Identity and Access Management Policy v2.6'),
      (61, 'How are security requirements defined and communicated to development teams?', 'Security requirements are derived from risk assessments, regulatory obligations, and a documented security standards library that is maintained by the security architecture team. Requirements are integrated into product requirements documentation and Agile user stories, with security acceptance criteria validated during sprint reviews. Developers have access to a self-service security knowledge portal with secure coding guidelines, reusable security libraries, and OWASP reference materials.', ARRAY['security requirements', 'SDLC', 'DevSecOps', 'Agile']::text[], 'Application Security Policy v1.6'),
      (62, 'What is your process for managing security-related findings from audits?', 'Audit findings—whether from internal audits, external audits, or regulatory examinations—are entered into a centralized findings management system with assigned owners, risk ratings, and target remediation dates. Progress is tracked monthly and reported to the CISO and Audit Committee. Findings that exceed 60 days past their target remediation date are escalated through a formal breach of SLA process.', ARRAY['audit management', 'compliance', 'findings remediation', 'governance']::text[], 'Audit Management Policy v1.2'),
      (63, 'How does your organization address OWASP Top 10 vulnerabilities in web applications?', 'OWASP Top 10 compliance is enforced through mandatory SAST/DAST scanning in the CI/CD pipeline with gates blocking deployment of critical OWASP findings. Developers receive OWASP-focused secure coding training annually, and application security assessments explicitly test for each OWASP Top 10 category. OWASP Top 10 coverage is included in annual third-party penetration test scopes.', ARRAY['OWASP', 'application security', 'web security', 'secure coding']::text[], 'Application Security Policy v1.6'),
      (64, 'Describe your approach to security for IoT and OT devices.', 'IoT and OT devices are inventoried and segmented onto isolated network zones with strict firewall rules governing inter-zone communication. Default credentials are changed at deployment, firmware is kept current through a dedicated patch process, and devices are monitored for anomalous network behavior via passive OT-aware network detection tools. Risk assessments are conducted for each IoT/OT device category, and high-risk devices are subject to enhanced monitoring.', ARRAY['IoT security', 'OT security', 'network segmentation', 'asset inventory']::text[], 'IoT and OT Security Policy v1.0'),
      (65, 'How is security information shared across your organization?', 'Security information sharing follows a tiered model: operational security updates and threat advisories are distributed to relevant technical teams through internal wikis and security newsletters, while strategic security information is communicated through executive dashboards and quarterly Board reports. The organization participates in industry ISACs and government information sharing programs to contribute to and benefit from collective defense intelligence.', ARRAY['information sharing', 'security communications', 'threat intelligence', 'ISAC']::text[], 'Threat Intelligence Policy v1.1'),
      (66, 'What controls are in place for secure file transfer?', 'Secure file transfer is enforced through approved managed file transfer (MFT) platforms and SFTP/HTTPS-based solutions for data exchange with external parties. Unencrypted FTP is prohibited by policy and blocked at the network perimeter. All file transfer activity involving sensitive data is logged, and transfers to external destinations require documented approval and are monitored for data exfiltration indicators.', ARRAY['secure file transfer', 'MFT', 'SFTP', 'data protection']::text[], 'Data Protection Policy v3.1'),
      (67, 'How does your organization perform security assessments of internal systems?', 'Internal security assessments are conducted on a risk-driven schedule including vulnerability scans of all networked assets weekly, internal penetration tests annually, and configuration compliance audits quarterly. Assessment findings are fed into the vulnerability management workflow for risk-rated remediation. Assessments of critical internal systems such as identity providers and SIEM are prioritized and results are reviewed by the CISO.', ARRAY['internal assessments', 'vulnerability scanning', 'penetration testing', 'compliance']::text[], 'Vulnerability Management Policy v2.2'),
      (68, 'What is your approach to securing machine identities and service accounts?', 'Machine identities and service accounts are inventoried and governed through the PAM platform with automated credential rotation. Service accounts follow least-privilege principles, are not permitted to be used interactively, and are reviewed quarterly to remove unnecessary accounts. Certificate-based authentication using short-lived certificates is preferred over long-lived passwords for service-to-service authentication.', ARRAY['machine identity', 'service accounts', 'PAM', 'certificate management']::text[], 'Identity and Access Management Policy v2.6'),
      (69, 'How does your organization manage risks related to open-source software?', 'Open-source software usage is governed by a policy requiring legal review of licenses and security review of components prior to adoption. SCA tooling continuously monitors production and development dependencies for known CVEs, and developers are alerted to newly disclosed vulnerabilities in used components through automated notifications. A curated internal catalog of approved open-source libraries is maintained to streamline adoption of vetted components.', ARRAY['open source security', 'SCA', 'license compliance', 'vulnerability management']::text[], 'Software Supply Chain Security Policy v1.1'),
      (70, 'Describe your data sovereignty and residency controls.', 'Data residency requirements are documented for each customer and regulatory jurisdiction and enforced through cloud region configurations, data center selection, and contractual obligations. Data classification labels include residency requirements, and automated controls prevent data from being processed or stored in unauthorized geographies. Data residency compliance is validated during annual audits and upon any infrastructure change affecting data processing locations.', ARRAY['data sovereignty', 'data residency', 'cloud security', 'compliance']::text[], 'Data Protection Policy v3.1'),
      (71, 'How does your organization manage cross-border data transfers?', 'Cross-border data transfers are governed by a transfer impact assessment process that evaluates the legal basis for transfer and the adequacy of destination country protections. Standard Contractual Clauses (SCCs) or Binding Corporate Rules (BCRs) are used for transfers from the EU where adequacy decisions are not in place. A register of international data transfers is maintained and reviewed annually by the DPO.', ARRAY['cross-border transfer', 'GDPR', 'SCCs', 'data sovereignty']::text[], 'Privacy and Data Protection Policy v2.5'),
      (72, 'What is your policy on the use of personal devices for work purposes?', 'BYOD usage is permitted within a defined framework requiring device enrollment in MDM, installation of an enterprise mobility management (EMM) profile that containerizes corporate data, and compliance with minimum security standards including OS version, encryption, and screen lock. Corporate data on BYOD devices is remotely wipeable independently of personal data. BYOD eligibility is limited to specific job roles and requires employee acceptance of the BYOD policy.', ARRAY['BYOD', 'MDM', 'mobile security', 'endpoint security']::text[], 'Mobile Device Management Policy v1.4'),
      (73, 'How does your organization detect and respond to phishing attacks?', 'Phishing detection is implemented through secure email gateway scanning, advanced threat protection with URL and attachment sandboxing, and DMARC enforcement to block spoofed sender domains. A one-click phishing report button is deployed in email clients, enabling employees to report suspicious emails for rapid SOC triage. Confirmed phishing campaigns targeting the organization trigger a threat intelligence update and SIEM rule tuning within 24 hours.', ARRAY['phishing', 'email security', 'incident response', 'awareness training']::text[], 'Email Security Policy v1.5'),
      (74, 'What is your process for managing security in outsourced or co-managed IT environments?', 'Outsourced and co-managed IT arrangements are subject to the same vendor risk management process as other third parties, including security due diligence, contractual security requirements, and right-to-audit clauses. Service Level Agreements include security-specific metrics such as patch compliance rates and incident response times. Joint security governance meetings are held quarterly to review security posture, open findings, and upcoming changes.', ARRAY['outsourcing', 'vendor management', 'MSSP', 'co-managed IT']::text[], 'Third-Party Risk Management Policy v1.9'),
      (75, 'Describe your approach to identity federation and SSO.', 'Single Sign-On (SSO) is implemented using SAML 2.0 and OIDC protocols federated through a central enterprise identity provider. All business applications are onboarded to SSO to centralize access control, and MFA is enforced at the identity provider level for all federated authentications. Federated identity trust relationships are reviewed annually, and orphaned or unused application integrations are revoked.', ARRAY['SSO', 'identity federation', 'SAML', 'OIDC']::text[], 'Authentication Policy v2.0'),
      (76, 'How do you ensure compliance with the NIST Cybersecurity Framework?', 'The NIST Cybersecurity Framework (CSF) 2.0 is used as the primary organizing structure for our information security program, with control maturity assessed against each CSF subcategory annually. Maturity scores are used to prioritize security investments and reported to the Board as part of the annual security program review. Gap remediation plans are tracked as formal projects with executive sponsorship.', ARRAY['NIST CSF', 'compliance', 'security program', 'maturity']::text[], 'Information Security Management System Policy v3.0'),
      (77, 'What security controls apply to your data backup infrastructure?', 'Backup infrastructure is subject to the same security controls as production systems, including encryption of backup data at rest and in transit, access controls limiting backup management to authorized administrators, and network segmentation isolating backup systems from general corporate traffic. Backup logs are monitored for unauthorized access or modification, and backup integrity checks are automated and reviewed weekly.', ARRAY['backup security', 'encryption', 'access control', 'monitoring']::text[], 'Backup and Recovery Policy v2.0'),
      (78, 'How does your organization manage and track security assets?', 'A comprehensive asset management program inventories all IT assets—hardware, software, cloud resources, and data assets—using automated discovery tools integrated with the configuration management database (CMDB). Assets are classified by criticality and data sensitivity, and asset ownership is assigned and reviewed annually. Security controls are mapped to asset classification to ensure appropriate protections are applied consistently.', ARRAY['asset management', 'CMDB', 'inventory', 'configuration management']::text[], 'IT Asset Management Policy v1.6'),
      (79, 'What controls are in place for protecting intellectual property?', 'Intellectual property is protected through a combination of data classification controls, DLP policies monitoring for IP-related content, access restrictions limiting exposure to authorized personnel, and legal agreements including NDAs and IP assignment clauses in employment contracts. Departing employees with access to sensitive IP are subject to enhanced offboarding procedures, and DLP alerts are tuned for IP-related data patterns.', ARRAY['intellectual property', 'DLP', 'data protection', 'confidentiality']::text[], 'Information Classification and Handling Policy v2.0'),
      (80, 'Describe your network intrusion detection and prevention capabilities.', 'Network IDS/IPS sensors are deployed at key network ingress/egress points and internal segmentation boundaries, providing signature-based and behavioral detection of malicious activity. Signatures are updated automatically through vendor threat intelligence feeds, and custom rules are developed based on threat intelligence relevant to our industry. IDS/IPS alerts are ingested into the SIEM and correlated with other security events for enriched investigation context.', ARRAY['IDS/IPS', 'network security', 'intrusion detection', 'SIEM']::text[], 'Network Security Policy v2.4'),
      (81, 'How is sensitive data handled in non-production environments?', 'Production data is prohibited from use in development, test, and staging environments by policy. Where realistic test data is required, a data anonymization and synthetic data generation process is used to create functionally equivalent data sets that contain no real PII or sensitive information. Access to non-production environments is controlled separately from production and reviewed quarterly.', ARRAY['test data management', 'data masking', 'non-production', 'privacy']::text[], 'Data Classification Policy v2.0'),
      (82, 'What is your approach to security for legacy systems?', 'Legacy systems unable to meet current security standards are subject to a formal risk acceptance process and compensating control framework that may include network isolation, enhanced monitoring, restricted access, and an accelerated decommission roadmap. All legacy systems are inventoried with their known security limitations documented, and risk acceptance is renewed annually with CISO approval. Decommission progress is tracked and reported to senior leadership quarterly.', ARRAY['legacy systems', 'compensating controls', 'risk management', 'decommission']::text[], 'IT Asset Management Policy v1.6'),
      (83, 'How does your organization handle suspected unauthorized access to customer data?', 'Suspected unauthorized access to customer data triggers immediate escalation to the incident response team for investigation under the Incident Response Plan. If the investigation confirms unauthorized access, customers are notified within 72 hours per GDPR requirements (or applicable regulatory deadlines), supported by a documented breach notification process overseen by Legal and the DPO. Post-incident forensics are conducted to determine root cause and prevent recurrence.', ARRAY['breach notification', 'incident response', 'GDPR', 'customer notification']::text[], 'Incident Response Plan v3.0'),
      (84, 'What is your policy on vulnerability disclosure and bug bounty programs?', 'A coordinated vulnerability disclosure (CVD) policy is published on our security page, providing researchers with clear channels to report discovered vulnerabilities, defined response timelines, and safe harbor provisions. A bug bounty program managed through a third-party platform offers rewards for qualifying vulnerability reports, with scope and reward tiers defined by asset criticality. Reported vulnerabilities are triaged within 5 business days and researchers receive status updates through the resolution lifecycle.', ARRAY['vulnerability disclosure', 'bug bounty', 'CVD', 'responsible disclosure']::text[], 'Vulnerability Disclosure Policy v1.0'),
      (85, 'How do you secure data processed by artificial intelligence or machine learning systems?', 'AI/ML systems processing sensitive data are subject to the same data governance and security controls as other systems, with data minimization applied to training datasets and PII anonymized or pseudonymized prior to use in model training. Model outputs are assessed for privacy risks including re-identification potential before deployment. Access to AI/ML platforms and training data is controlled through RBAC, and audit logs of data access are maintained.', ARRAY['AI security', 'ML security', 'data governance', 'privacy']::text[], 'AI and Machine Learning Security Policy v1.0'),
      (86, 'Describe your approach to security for microservices architectures.', 'Microservices communicate over encrypted channels using mTLS enforced by a service mesh, and each service authenticates using short-lived identity certificates issued by an internal certificate authority. Authorization policies are defined at the service mesh layer implementing zero-trust principles between services. API gateways enforce rate limiting and input validation for external-facing service endpoints, and service-level security configurations are version-controlled and reviewed through the change management process.', ARRAY['microservices', 'service mesh', 'mTLS', 'zero trust']::text[], 'Application Security Policy v1.6'),
      (87, 'What controls are in place for securing serverless functions?', 'Serverless functions are deployed with least-privilege IAM roles granting only the specific permissions required for each function''s operation. Code is scanned for vulnerabilities and hardcoded secrets through the CI/CD pipeline prior to deployment, and function dependencies are managed through SCA tooling. Execution logs are captured and forwarded to the SIEM, and abnormal invocation patterns trigger automated alerts for SOC investigation.', ARRAY['serverless security', 'cloud security', 'IAM', 'least privilege']::text[], 'Cloud Security Policy v1.7'),
      (88, 'How does your organization conduct and document threat modeling?', 'Threat modeling is a mandatory activity in the security design review process for new systems and significant changes, using STRIDE methodology to identify potential threats and DREAD or CVSS for risk rating. Output artifacts including data flow diagrams, identified threats, and recommended mitigations are documented and stored in the security architecture repository. Threat models are reviewed and updated when material changes to system architecture occur.', ARRAY['threat modeling', 'STRIDE', 'security architecture', 'design review']::text[], 'Security Architecture Review Policy v1.0'),
      (89, 'What is your approach to managing security in hybrid cloud environments?', 'Hybrid cloud security is governed by a unified security policy that applies consistent controls across on-premises and cloud environments, with a CSPM tool monitoring cloud posture and a SIEM aggregating logs from all environments. Identity is managed through a federated identity provider enabling consistent access policies regardless of resource location. Network connectivity between on-premises and cloud environments is protected through encrypted tunnels with strict firewall rule sets governing permitted traffic.', ARRAY['hybrid cloud', 'CSPM', 'identity federation', 'network security']::text[], 'Cloud Security Policy v1.7'),
      (90, 'How does your organization ensure the availability and resilience of critical systems?', 'Critical system availability is designed for based on defined RTO and RPO targets, with redundant infrastructure deployed across multiple availability zones or geographic regions. Automated health monitoring and alerting notify on-call teams of degraded or failed services, and self-healing automation is implemented where feasible to reduce mean time to recovery. Resilience is validated through regular chaos engineering exercises and annual DR failover tests.', ARRAY['high availability', 'resilience', 'disaster recovery', 'business continuity']::text[], 'Business Continuity Policy v2.1'),
      (91, 'Describe your approach to regulatory compliance monitoring.', 'Regulatory compliance is tracked through a dedicated GRC platform that maps control obligations to specific regulatory frameworks including GDPR, HIPAA, SOC 2, PCI DSS, and ISO 27001. Controls are continuously assessed through automated testing where available, with manual evidence collection for controls not amenable to automation. Compliance dashboards provide real-time visibility into control status, and emerging regulatory changes are tracked through legal and compliance monitoring services.', ARRAY['regulatory compliance', 'GRC', 'continuous monitoring', 'frameworks']::text[], 'Compliance Management Policy v1.5'),
      (92, 'What is your approach to managing user privileges in cloud identity and access management?', 'Cloud IAM policies are governed by least-privilege principles enforced through policy-as-code frameworks that prevent overly permissive role assignments from being deployed. All cloud IAM roles and policies are version-controlled, and changes require peer review and security team approval through the CI/CD pipeline. Unused IAM permissions and stale role assignments are identified through cloud entitlement management tooling and remediated on a 30-day cycle.', ARRAY['cloud IAM', 'least privilege', 'entitlement management', 'policy-as-code']::text[], 'Cloud Security Policy v1.7'),
      (93, 'How is security considered during product end-of-life and decommissioning?', 'Product decommissioning follows a documented end-of-life process that includes secure data migration or deletion with certificates of destruction, revocation of all service accounts and API keys, removal of DNS entries and firewall rules, and archival of relevant documentation. Decommission checklists are maintained per system type and reviewed by the security team prior to completion sign-off. Decommissioned systems are removed from asset inventories, monitoring, and vulnerability management scopes.', ARRAY['decommissioning', 'end-of-life', 'data disposal', 'asset management']::text[], 'IT Asset Management Policy v1.6'),
      (94, 'How does your organization implement and manage security information and event management (SIEM)?', 'Our SIEM platform ingests structured and unstructured log data from over 200 source types including firewalls, endpoints, cloud services, identity providers, and applications, normalized into a common data model for consistent correlation. Detection use cases are developed, peer-reviewed, and mapped to MITRE ATT&CK techniques before activation in production, with a formal use case lifecycle covering creation, tuning, and retirement. SIEM health metrics including ingestion rates, alert volumes, and false positive ratios are reviewed weekly by the security operations team.', ARRAY['SIEM', 'security monitoring', 'log management', 'MITRE ATT&CK']::text[], 'Security Monitoring and Logging Policy v2.3'),
      (95, 'What is your organization''s approach to security for remote desktop and administrative protocols?', 'Administrative protocols including RDP, SSH, and WinRM are restricted to authorized jump servers or PAM-mediated sessions, with direct access from user endpoints blocked at the network perimeter. All administrative sessions are recorded and retained for 90 days, and connection attempts to administrative ports from unauthorized sources generate real-time SIEM alerts. Protocol versions with known critical vulnerabilities are disabled by policy and enforced through configuration compliance scanning.', ARRAY['remote desktop', 'RDP', 'SSH', 'privileged access']::text[], 'Privileged Access Management Policy v1.6'),
      (96, 'Describe the controls used to protect against ransomware attacks.', 'Ransomware defenses are layered across prevention, detection, and recovery capabilities. Prevention controls include EDR with behavioral blocking, email security with attachment sandboxing, restricted macro execution, and application allowlisting on critical servers. Detection relies on SIEM rules tuned for ransomware behavioral patterns such as rapid file encryption and shadow copy deletion, with automated response playbooks isolating affected endpoints within minutes of confirmed detection. Immutable offline backups with tested recovery procedures ensure business continuity in the event of a successful attack.', ARRAY['ransomware', 'EDR', 'backup', 'incident response']::text[], 'Ransomware Preparedness Policy v1.0'),
      (97, 'How does your organization manage the security of its public-facing infrastructure?', 'External attack surface management is performed through continuous automated scanning of internet-exposed assets, supplemented by quarterly red team assessments and an annual full-scope external penetration test. A vulnerability management workflow prioritizes internet-facing findings above internal findings at equivalent severity levels. The external asset inventory is reconciled monthly against DNS and certificate transparency logs to identify shadow IT and unauthorized exposures.', ARRAY['external attack surface', 'penetration testing', 'vulnerability management', 'internet-facing']::text[], 'Vulnerability Management Policy v2.2'),
      (98, 'What is your process for communicating security incidents to affected parties?', 'Security incident communication follows a documented notification matrix defining stakeholder groups, communication channels, and timing obligations based on incident classification and regulatory requirements. Customer notifications for data security incidents are managed by Legal and the DPO, with draft communications reviewed prior to issue to ensure accuracy and regulatory compliance. Post-incident, a root cause summary is made available to affected customers where appropriate to support their own risk assessments.', ARRAY['breach notification', 'incident communication', 'GDPR', 'stakeholder management']::text[], 'Incident Response Plan v3.0'),
      (99, 'What security assurances do you provide for your software build and release pipeline?', 'The software build pipeline is hardened with access controls limiting modification rights to authorized CI/CD service accounts, all build artifacts are signed using code signing certificates traceable to an internal certificate authority, and artifact integrity is verified at each deployment stage. Pipeline configurations are version-controlled and changes require security team review. Third-party build tool dependencies are managed through a curated internal package mirror subject to vulnerability scanning.', ARRAY['CI/CD security', 'code signing', 'pipeline integrity', 'supply chain security']::text[], 'Secure Development Lifecycle Policy v2.2'),
      (100, 'How does your organization handle security during significant operational events such as major releases or infrastructure migrations?', 'High-risk operational events are designated as security-sensitive periods, during which enhanced monitoring thresholds are activated, change freeze windows are enforced, and incident response team availability is increased. Pre-event security reviews validate that changes are fully tested and rollback procedures are documented and rehearsed. A dedicated war room channel is established for rapid cross-functional communication during the event window, and a post-event security review is conducted within 5 business days.', ARRAY['operational security', 'change management', 'incident response', 'risk management']::text[], 'Change Management Policy v1.7')
    ) AS v(ord, q, a, t, s)
   ORDER BY v.ord;
END $kb$;
-- END KNOWLEDGE BASE

