  VALUES ('bluefin-security-questionnaire.xlsx', 12, opp) RETURNING id INTO sess;
  INSERT INTO public.rfi_questions (session_id, position, question, customer_ref, generated_answer, confidence, retrieval_score, sources_json, answerability, verdict, gate, gate_reason, language, embedding_model, judge_model, judge_best_ref, judge_reason, draft_model, prompt_version, calibration_set, draft_kind, cited_refs, processing_note, processed_at) VALUES
    (sess, 0, 'How do you protect data at rest in your platform?', 'A1', 'We encrypt all data at rest using AES-256 across storage systems, databases, and backup media. Encryption keys are managed through a dedicated key management service (KMS) with strict access controls and regular rotation schedules. Hardware Security Modules (HSMs) protect the root keys. We validate encryption coverage through quarterly audits.

[References: KB-0001]', 1, 0.6298443826942993, '[{"id":"KB-0001","score":0.6298443826942993}]'::jsonb, 2.629844382694299, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0001', 'KB-0001 directly describes how data at rest is protected: AES-256 encryption across storage, databases, and backups, with KMS and HSM key management.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0001']::text[], NULL, '2026-10-25T07:22:30.012Z'::timestamptz),
    (sess, 1, 'Describe how user access is granted, reviewed and removed.', 'A2', 'We grant access through an Identity Governance and Administration (IGA) platform that automates provisioning, de-provisioning and access recertification. All access requests require documented business justification and manager approval before provisioning. We use a least-privilege, role-based access control (RBAC) model aligned with ISO 27001 Annex A controls. All access rights are reviewed quarterly through a formal access recertification process. Terminated user access is revoked within 4 hours of HR notification. Privileged access is further restricted through Privileged Access Management (PAM) tooling with session recording.

[References: KB-0024, KB-0003]', 0.892, 0.5295053240342207, '[{"id":"KB-0024","score":0.5295053240342207},{"id":"KB-0003","score":0.480736147852047}]'::jsonb, 2.5295053240342207, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0024', 'KB-0024 covers granting access (manager approval and documented justification) and removal (revocation within 4 hours of HR notice), and mentions recertification workflows. KB-0003 adds quarterly access reviews, so all three parts are answered.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0024', 'KB-0003']::text[], NULL, '2026-10-25T07:22:29.949Z'::timestamptz),
    (sess, 2, 'How are security patches assessed and rolled out?', 'A3', 'We manage security patches on a defined cycle. Critical patches are deployed within 24–72 hours of release, high-severity patches within 7 days, and routine patches within 30 days. We use automated patch deployment for endpoints and servers where possible. Exceptions are tracked and risk-accepted by our CISO. We review patch compliance metrics weekly and escalate non-compliant assets through our vulnerability management workflow.

[References: KB-0037]', 0.942, 0.56830859277055, '[{"id":"KB-0037","score":0.56830859277055}]'::jsonb, 2.56830859277055, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0037', 'KB-0037 describes how patches are assessed by severity, with deployment timelines per tier, automated rollout, tracked exceptions, and weekly compliance review, which covers both assessment and rollout.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0037']::text[], NULL, '2026-10-25T07:22:31.879Z'::timestamptz),
    (sess, 3, 'What logging and monitoring do you have in place to detect attacks?', 'A4', 'We aggregate logs from all critical systems, including firewalls, endpoints, identity providers, cloud platforms, and applications, in a centralized SIEM platform. Log retention is 12 months online and 24 months archived. Detection rules are tuned based on threat intelligence and mapped to MITRE ATT&CK tactics and techniques. Our security operations center (SOC) monitors alerts 24/7 and follows documented escalation procedures.

[References: KB-0021]', 0.942, 0.6050922598599714, '[{"id":"KB-0021","score":0.6050922598599714}]'::jsonb, 2.6050922598599713, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0021', 'KB-0021 describes a centralized SIEM aggregating logs from critical systems, detection rules mapped to MITRE ATT&CK, and 24/7 SOC monitoring with escalation, which directly answers how attacks are detected.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0021']::text[], NULL, '2026-10-25T07:22:34.401Z'::timestamptz),
    (sess, 4, 'How do you test that backups can actually be restored?', 'A5', 'We validate backup integrity through automated verification checks and conduct manual restoration tests quarterly. Recovery procedures are documented in run books. We also test RTO and RPO metrics against defined targets during annual disaster recovery exercises, and report the results.

[References: KB-0023]', 0.892, 0.4819225648116013, '[{"id":"KB-0023","score":0.4819225648116013}]'::jsonb, 2.4819225648116015, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0023', 'KB-0023 states that backup integrity is validated through manual restoration tests conducted quarterly, plus RTO/RPO testing during annual DR exercises, directly answering how restorability is tested.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0023']::text[], NULL, '2026-10-25T07:22:35.417Z'::timestamptz),
    (sess, 5, 'How do you secure containerised workloads in your cloud environment?', 'A6', 'We secure containerised workloads in several layers. Container images are scanned in our CI/CD pipeline using SCA and vulnerability analysis tools, and are stored in a private registry subject to policy-based admission controls. Runtime security monitoring detects anomalous container behaviour. Our Kubernetes clusters are hardened per CIS benchmarks, with RBAC enforced at the namespace level. Secrets for containerised workloads are managed in a dedicated vault solution rather than environment variables.

[References: KB-0041]', 1, 0.7405122695499418, '[{"id":"KB-0041","score":0.7405122695499418}]'::jsonb, 2.7405122695499418, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0041', 'KB-0041 directly describes how containerised workloads are secured: image scanning, private registry with admission controls, runtime monitoring, CIS-hardened Kubernetes with RBAC, and vault-based secrets management.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0041']::text[], NULL, '2026-10-25T07:22:36.732Z'::timestamptz),
    (sess, 6, 'What is the annual subscription price for 250 users?', 'A7', 'Pricing question: a person answers this. No draft is written, and pricing answers are never added to the knowledge base automatically.', 0, 0.21733557026961292, '[{"id":"KB-0055","score":0.21733557026961292},{"id":"KB-0020","score":0.2035066300642761},{"id":"KB-0025","score":0.20314476811001095}]'::jsonb, 0.21733557026961292, 'no', 'pricing', 'Rules matched: price. Classifier: The question asks for the annual subscription price for 250 users, which is a request for a price.', 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0055', 'The entries cover privileged user monitoring, security awareness training, and zero trust architecture, but none mention subscription pricing or the price for 250 users, so the question cannot be answered from them.', NULL, NULL, '2026-10-22.3 (calibrate split)', 'person_required', ARRAY[]::text[], NULL, '2026-10-25T07:22:36.013Z'::timestamptz),
    (sess, 7, 'Will you accept unlimited liability for losses caused by a data breach?', 'A8', 'No confident match in the knowledge base: the closest entries are listed under Sources, but they may not answer this question. It needs an answer written by a person.', 0, 0.32703354830941544, '[{"id":"KB-0083","score":0.32703354830941544},{"id":"KB-0034","score":0.299167604329551},{"id":"KB-0009","score":0.2928112195407919}]'::jsonb, 0.32703354830941544, 'no', 'legal', 'Rules matched: liability. Classifier: The question asks the company to accept unlimited liability for losses, which is a contractual liability term.', 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0009', 'The entries cover incident handling, data loss prevention, and vendor risk management but say nothing about accepting unlimited liability for breach losses, which is the specific commitment asked for.', NULL, NULL, '2026-10-22.3 (calibrate split)', 'insufficient_evidence', ARRAY[]::text[], NULL, '2026-10-25T07:22:37.267Z'::timestamptz),
    (sess, 8, 'What is your mean time to detect a security incident?', 'A9', 'No confident match in the knowledge base: the closest entries are listed under Sources, but they may not answer this question. It needs an answer written by a person.', 0, 0.5655337610443019, '[{"id":"KB-0006","score":0.5655337610443019},{"id":"KB-0007","score":0.5316645622105987},{"id":"KB-0021","score":0.5295243980033442}]'::jsonb, 0.5655337610443019, 'no', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0021', 'The entries describe SIEM monitoring, 24/7 SOC coverage, and incident response SLAs, but none states a mean time to detect figure, which is the specific metric asked for.', NULL, NULL, '2026-10-22.3 (calibrate split)', 'insufficient_evidence', ARRAY[]::text[], NULL, '2026-10-25T07:22:37.758Z'::timestamptz),
    (sess, 9, 'フィッシング攻撃をどのように検知し、対応していますか？', 'A10', '当社は、フィッシング攻撃を次の方法で検知しています。セキュアメールゲートウェイによるメールスキャン、URLおよび添付ファイルのサンドボックス検査を含む高度な脅威防御、なりすましの送信元ドメインを遮断するDMARCの適用です。メールクライアントにはワンクリックの報告ボタンを導入しており、従業員は不審なメールをSOCへ報告できます。SOCは報告を迅速にトリアージします。当社を標的とした確認済みのフィッシングキャンペーンに対しては、24時間以内に脅威インテリジェンスを更新し、SIEMのルールを調整します。

