  INSERT INTO public.rfi_sessions (file_name, question_count, opportunity_id)
  VALUES ('harbour-rfq-security-schedule.xlsx', 6, opp) RETURNING id INTO sess;
  INSERT INTO public.rfi_questions (session_id, position, question, customer_ref, generated_answer, confidence, retrieval_score, sources_json, answerability, verdict, gate, gate_reason, language, embedding_model, judge_model, judge_best_ref, judge_reason, draft_model, prompt_version, calibration_set, draft_kind, cited_refs, processing_note, processed_at) VALUES
    (sess, 0, 'What SOC 2 reports do you hold?', 'S1', 'We hold a SOC 2 Type II report covering the Trust Services Criteria for Security, Availability, and Confidentiality. It was issued by an independent AICPA-accredited auditor, covers an audit period of a minimum of six months, and is refreshed annually. Bridge letters are available on request for periods between reports. Copies are available under NDA to qualified prospective and current customers.

[References: KB-0017]', 0.892, 0.5488312761657221, '[{"id":"KB-0017","score":0.5488312761657221}]'::jsonb, 2.548831276165722, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0017', 'KB-0017 directly states the company holds a SOC 2 Type II report covering Security, Availability, and Confidentiality, which answers what SOC 2 reports are held.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0017']::text[], NULL, '2026-10-25T07:23:03.257Z'::timestamptz),
    (sess, 1, 'How do you manage privileged accounts?', 'S2', 'We manage privileged accounts through a Privileged Access Management (PAM) solution. Privileged accounts are inventoried, and access is granted just-in-time rather than as standing access wherever possible. Elevation is time-limited and approval-gated. Passwords are stored in a vault with automated rotation, and privileged sessions are recorded. Privileged account activity is monitored with enhanced monitoring and anomaly alerting in our SIEM.

[References: KB-0031]', 0.942, 0.6159884170053993, '[{"id":"KB-0031","score":0.6159884170053993}]'::jsonb, 2.6159884170053993, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0031', 'KB-0031 directly describes how privileged accounts are managed: PAM solution, just-in-time access, session recording, password vaulting with rotation, and SIEM monitoring of privileged activity.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0031']::text[], NULL, '2026-10-25T07:23:04.455Z'::timestamptz),
    (sess, 2, 'Describe your approach to single sign-on and identity federation.', 'S3', 'We implement single sign-on (SSO) using SAML 2.0 and OIDC protocols, federated through a central enterprise identity provider. All business applications are onboarded to SSO to centralize access control. Multi-factor authentication (MFA) is enforced at the identity provider level for all federated authentications. We review federated identity trust relationships annually and revoke orphaned or unused application integrations.

[References: KB-0075]', 1, 0.6603944248826867, '[{"id":"KB-0075","score":0.6603944248826867}]'::jsonb, 2.6603944248826865, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0075', 'KB-0075 directly describes the SSO and identity federation approach, naming SAML 2.0 and OIDC, a central identity provider, MFA enforcement, and annual trust reviews, matching the question.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0075']::text[], NULL, '2026-10-25T07:23:02.571Z'::timestamptz),
    (sess, 3, 'How are your build and release pipelines secured?', 'S4', 'We harden our software build pipeline with access controls that limit modification rights to authorized CI/CD service accounts. All build artifacts are signed with code signing certificates traceable to an internal certificate authority, and artifact integrity is verified at each deployment stage. Pipeline configurations are version-controlled, and changes require security team review. Third-party build tool dependencies are managed through a curated internal package mirror subject to vulnerability scanning.

[References: KB-0099]', 1, 0.7128342050730675, '[{"id":"KB-0099","score":0.7128342050730675}]'::jsonb, 2.7128342050730674, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0099', 'KB-0099 directly describes how the build and release pipeline is secured: restricted CI/CD access, signed artifacts, integrity checks at each deployment stage, reviewed pipeline configuration changes, and vetted dependencies.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0099']::text[], NULL, '2026-10-25T07:23:08.956Z'::timestamptz),
    (sess, 4, 'How do you secure email against phishing and spoofing?', 'S5', 'We secure email through a secure email gateway that provides anti-phishing, anti-malware, and spam filtering. We use DMARC, DKIM, and SPF records to prevent domain spoofing. Advanced threat protection scans attachments and URLs in sandboxed environments, and suspicious emails are quarantined for review. Our security awareness training includes phishing simulation exercises.

[References: KB-0035]', 1, 0.6696145686287308, '[{"id":"KB-0035","score":0.6696145686287308}]'::jsonb, 2.669614568628731, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0035', 'KB-0035 directly describes anti-phishing filtering via a secure email gateway and DMARC, DKIM, and SPF records to prevent domain spoofing, which is exactly what the question asks about.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0035']::text[], NULL, '2026-10-25T07:23:10.326Z'::timestamptz),
    (sess, 5, 'How do you manage security for staff working remotely?', 'S6', 'Remote workers are subject to the same security policies as on-site employees. We enforce these policies through MDM, endpoint protection, and ZTNA-based access controls. Security awareness training includes modules on home office risks, such as unsecured Wi-Fi and physical eavesdropping. VPN use is mandatory when accessing sensitive systems. Remote worker equipment is company-issued and managed.

[References: KB-0043]', 1, 0.6854222469969923, '[{"id":"KB-0043","score":0.6854222469969923}]'::jsonb, 2.685422246996992, 'yes', NULL, NULL, 'en', 'voyage-4', 'claude-haiku-5-5', 'KB-0043', 'KB-0043 directly describes how remote workers are secured, covering policy enforcement, MDM and endpoint protection, ZTNA and VPN access controls, training, and company-issued managed equipment, which answers the question.', 'claude-haiku-5-5', 'draft-2026-10-23.1', '2026-10-22.3 (calibrate split)', 'generated', ARRAY['KB-0043']::text[], NULL, '2026-10-25T07:23:10.068Z'::timestamptz);
  PERFORM public.bulk_accept(sess, 0.8);
  -- Everything else decided individually: drafts accepted as written, the rest marked not answered.
  FOR qid, kind IN SELECT q.id, q.draft_kind FROM public.rfi_questions q WHERE q.session_id = sess AND q.status = 'pending' ORDER BY q.position LOOP
    UPDATE public.rfi_questions SET status = CASE WHEN kind IN ('generated', 'assembled') THEN 'accepted' ELSE 'skipped' END WHERE id = qid;
  END LOOP;
  PERFORM public.record_export(sess);
  PERFORM public.archive_response(opp, 'won');
